    #include <stdio.h>
    #include "export_adapter.h"
    #include "../../core/entities/cq_palette.h"

    cq_export_result_t export_palette_as_svg(const cq_palette_t* palette, const char* file_path, bool is_pro) {
        if (!palette || !file_path) return CQ_EXPORT_ERROR_INVALID_DATA;

        FILE* svg_file = fopen(file_path, "w");
        if (!svg_file) return CQ_EXPORT_ERROR_FILE_IO;

        fprintf(svg_file, "<svg width=\"%d\" height=\"100\" xmlns=\"http://www.w3.org/2000/svg\">\n", palette->sample_count * 100);

        for (int i = 0; i < palette->sample_count; ++i) {
            // Assuming cq_color_sample_t has a hex_code string member
            fprintf(svg_file, "  <rect x=\"%d\" y=\"0\" width=\"100\" height=\"100\" fill=\"#%s\" />\n", i * 100, palette->samples[i].hex_code);
        }

        if (!is_pro) {
            fprintf(svg_file, "  <text x=\"10\" y=\"90\" font-family=\"sans-serif\" font-size=\"10\" fill=\"gray\">Exported with ChromaticQuiver</text>\n");
        }

        fprintf(svg_file, "</svg>\n");
        fclose(svg_file);

        return CQ_EXPORT_SUCCESS;
    }
    ```
